using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddChatClient(chatBuilder =>
    chatBuilder.UseOpenAIChatClient(
        builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18"));

builder.Services.AddSingleton<Notebook>();
builder.Services.AddSingleton<WebSearchTool>();
builder.Services.AddSingleton<NoteTool>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var notebook = host.Services.GetRequiredService<Notebook>();
var webSearchTool = host.Services.GetRequiredService<WebSearchTool>();
var noteTool = host.Services.GetRequiredService<NoteTool>();
var logger = host.Services.GetRequiredService<ILoggerFactory>().CreateLogger("ResearchAgent");

var agent = new ChatClientAgent(chatClient,
    """
    You are a research agent. Your job is to research a topic thoroughly by:
    1. Searching the web for relevant information using the search tool.
    2. Taking notes on key findings using the note-taking tool.
    3. After gathering enough information (at least 3 searches), produce a final summary.

    Always search from multiple angles and take notes on each finding before summarizing.
    """)
{
    Name = "Researcher",
    Tools = [.. AIFunctionFactory.Create(webSearchTool), .. AIFunctionFactory.Create(noteTool)],
};

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 15,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }

    logger.LogDebug("Agent step: Role={Role}, ContentLength={Length}",
        message.Role, message.Text?.Length ?? 0);
}

Console.WriteLine();

if (notebook.Notes.Count > 0)
{
    Console.WriteLine("\n=== Research Notes ===");
    foreach (var note in notebook.Notes)
    {
        Console.WriteLine($"• {note}");
    }
}

/// <summary>Stores notes collected during the research session.</summary>
public sealed class Notebook
{
    private readonly List<string> _notes = [];
    public IReadOnlyList<string> Notes => _notes;

    public void Add(string note)
    {
        _notes.Add(note);
    }
}

/// <summary>Provides web search capabilities to the agent.</summary>
public sealed class WebSearchTool(ILogger<WebSearchTool> logger)
{
    private static readonly HttpClient HttpClient = new();

    [Description("Searches the web for information on a query. Returns a list of search result snippets.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up")] string query,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Searching web for: {Query}", query);
        Console.WriteLine($"  🔍 Searching: {query}");

        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_redirect=1&no_html=1";
            var response = await HttpClient.GetStringAsync(url, cancellationToken);

            var doc = JsonDocument.Parse(response);
            var results = new List<string>();

            if (doc.RootElement.TryGetProperty("Abstract", out var abstractText)
                && abstractText.GetString() is { Length: > 0 } abs)
            {
                results.Add($"Summary: {abs}");
            }

            if (doc.RootElement.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text)
                        && text.GetString() is { Length: > 0 } t)
                    {
                        results.Add(t);
                    }
                }
            }

            if (results.Count == 0)
            {
                results.Add($"No detailed results found for '{query}'. Try rephrasing the search.");
            }

            return string.Join("\n\n", results);
        }
        catch (Exception ex)
        {
            logger.LogWarning(ex, "Web search failed for query: {Query}", query);
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }
}

/// <summary>Provides note-taking capabilities to the agent.</summary>
public sealed class NoteTool(Notebook notebook, ILogger<NoteTool> logger)
{
    [Description("Saves a research note. Use this to record key findings from search results.")]
    public string TakeNote(
        [Description("The note content to save")] string note)
    {
        notebook.Add(note);
        logger.LogInformation("Note taken: {Note}", note);
        Console.WriteLine($"  📝 Note saved ({notebook.Notes.Count} total)");
        return $"Note saved. You now have {notebook.Notes.Count} note(s).";
    }

    [Description("Retrieves all notes taken so far during the research session.")]
    public string GetNotes()
    {
        if (notebook.Notes.Count == 0)
        {
            return "No notes taken yet.";
        }

        return string.Join("\n", notebook.Notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

