using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

var builder = Host.CreateApplicationBuilder(args);
builder.Logging.SetMinimumLevel(LogLevel.Warning);

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(pipeline => pipeline
    .UseOpenAIChatClient(modelId));

builder.Services.AddSingleton<Notebook>();
builder.Services.AddSingleton<ResearchTools>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();
var loggerFactory = host.Services.GetRequiredService<ILoggerFactory>();

var tools = AIFunctionFactory.Create(researchTools);

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information using the SearchWeb tool.
        2. Taking notes on key findings using the TakeNote tool.
        3. After gathering enough information (at least 3 searches), reviewing your notes with GetNotes,
           then producing a final comprehensive summary.

        Always search from multiple angles and take notes on each finding before summarizing.
        """,
    name: "Researcher",
    description: "An agent that researches topics using web search and note-taking.",
    tools: tools);

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var session = await agent.CreateSessionAsync();

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session);

Console.WriteLine(response.Text);

var notebook = host.Services.GetRequiredService<Notebook>();
if (notebook.Notes.Count > 0)
{
    Console.WriteLine("\n=== Research Notes ===");
    foreach (var note in notebook.Notes)
    {
        Console.WriteLine($"  • {note}");
    }
}

/// <summary>Stores notes collected during the research session.</summary>
public sealed class Notebook
{
    private readonly List<string> _notes = [];
    public IReadOnlyList<string> Notes => _notes;

    public void Add(string note) => _notes.Add(note);
}

/// <summary>Provides web search and note-taking tools for the research agent.</summary>
public sealed class ResearchTools(Notebook notebook, ILogger<ResearchTools> logger)
{
    private static readonly HttpClient HttpClient = new();

    [Description("Searches the web for information on a query. Returns search result snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up")] string query,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Searching web for: {Query}", query);
        Console.WriteLine($"  🔍 Searching: {query}");

        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_redirect=1&no_html=1";
            var json = await HttpClient.GetStringAsync(url, cancellationToken);

            var doc = JsonDocument.Parse(json);
            var results = new List<string>();

            if (doc.RootElement.TryGetProperty("Abstract", out var abstractText)
                && abstractText.GetString() is { Length: > 0 } abs)
            {
                results.Add($"Summary: {abs}");
            }

            if (doc.RootElement.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var item in topics.EnumerateArray().Take(5))
                {
                    if (item.TryGetProperty("Text", out var text)
                        && text.GetString() is { Length: > 0 } t)
                    {
                        results.Add(t);
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No detailed results found for '{query}'. Try rephrasing the search.";
        }
        catch (Exception ex)
        {
            logger.LogWarning(ex, "Web search failed for query: {Query}", query);
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Saves a research note. Use this to record key findings from search results.")]
    public string TakeNote(
        [Description("The note content to save")] string note)
    {
        notebook.Add(note);
        logger.LogInformation("Note taken ({Count} total)", notebook.Notes.Count);
        Console.WriteLine($"  📝 Note saved ({notebook.Notes.Count} total)");
        return $"Note saved. You now have {notebook.Notes.Count} note(s).";
    }

    [Description("Retrieves all notes taken so far during the research session.")]
    public string GetNotes()
    {
        if (notebook.Notes.Count == 0)
        {
            return "No notes taken yet.";
        }

        return string.Join("\n", notebook.Notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

